    fun pathData(genre: String?): String =
        if (genre == null) NEUTRAL else PATHS[genre] ?: NEUTRAL

    private val composeCache = HashMap<String, Path>()

    fun composePath(genre: String?): Path {
        val d = pathData(genre)
        return composeCache.getOrPut(d) { PathParser().parsePathString(d).toPath() }
    }

    /** Рисует иконку на обычном android Canvas (для карточки). */
    fun draw(
        canvas: AndroidCanvas,
        genre: String?,
        x: Float,
        y: Float,
        size: Float,
        color: Int,
        alpha: Int = 255
    ) {
        val paint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
            style = Paint.Style.FILL
            this.color = color
            this.alpha = alpha
        }
        val path = CorePathParser.createPathFromPathData(pathData(genre))
        canvas.save()
        canvas.translate(x, y)
        canvas.scale(size / 24f, size / 24f)
        canvas.drawPath(path, paint)
        canvas.restore()
    }
}

@Composable
fun GenreIcon(
    genre: String?,
    modifier: Modifier = Modifier,
    iconSize: Dp = 20.dp,
    tint: Color = LocalContentColor.current
) {
    val path = remember(genre) { GenreIcons.composePath(genre) }
    Canvas(modifier = modifier.size(iconSize)) {
        val k = this.size.width / 24f
        scale(scale = k, pivot = Offset.Zero) {
            drawPath(path, tint)
        }
    }
}